import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index + 1])
    index += 2

    edges = []
    for _ in range(n - 1):
        u = int(data[index]) - 1
        v = int(data[index + 1]) - 1
        edges.append((u, v))
        index += 2

    operations = []
    for _ in range(m):
        a = int(data[index]) - 1
        b = int(data[index + 1]) - 1
        operations.append((a, b))
        index += 2

    # Build the tree
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # Depth-first search to assign depths and parent pointers
    depth = [0] * n
    parent = [-1] * n
    stack = [(0, -1)]
    while stack:
        node, par = stack.pop()
        parent[node] = par
        for neighbor in tree[node]:
            if neighbor != par:
                depth[neighbor] = depth[node] + 1
                stack.append((neighbor, node))

    # Binary lifting for LCA
    MAX_LOG = 17
    up = [[-1] * MAX_LOG for _ in range(n)]

    for node in range(n):
        up[node][0] = parent[node]

    for j in range(1, MAX_LOG):
        for node in range(n):
            if up[node][j - 1] != -1:
                up[node][j] = up[up[node][j - 1]][j - 1]

    def lca(u, v):
        if depth[u] > depth[v]:
            u, v = v, u

        diff = depth[v] - depth[u]
        for j in range(MAX_LOG):
            if diff & (1 << j):
                v = up[v][j]

        if u == v:
            return u

        for j in range(MAX_LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]

        return up[u][0]

    # Union-Find structure
    size = [1] * n
    parent_set = list(range(n))

    def find(x):
        if parent_set[x] != x:
            parent_set[x] = find(parent_set[x])
        return parent_set[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if size[root_x] < size[root_y]:
                root_x, root_y = root_y, root_x
            parent_set[root_y] = root_x
            size[root_x] += size[root_y]

    # Process operations
    for a, b in operations:
        l = lca(a, b)
        union(a, l)
        union(b, l)

    # Count common numbers
    result = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            if find(i) == find(j):
                result[i] += 1
                result[j] += 1

    # Print the result
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
